CREATE TABLE ds.types (
  c_int INT64, c_num NUMERIC, c_bignum BIGNUMERIC, c_float FLOAT64, c_bool BOOL, c_str STRING, c_bytes BYTES,
  c_date DATE, c_time TIME, c_dt DATETIME, c_ts TIMESTAMP, c_geo GEOGRAPHY, c_json JSON,
  c_rec STRUCT<k STRING, v INT64>, c_arr ARRAY<INT64>, c_rarr ARRAY<STRUCT<k STRING>>
);
INSERT INTO ds.types VALUES (
  9223372036854775807, NUMERIC '-99999999999999999999999999999.999999999', BIGNUMERIC '0.12345678901234567890123456789012345678',
  1.5, true, 'héllo', b'\x00\xff', DATE '2024-02-29', TIME '23:59:59.123456', DATETIME '2024-02-29 12:34:56.789',
  TIMESTAMP '2024-02-29 12:34:56.789+02', ST_GEOGPOINT(30.5, 50.45), JSON '{"a":[1,2]}',
  STRUCT('x' AS k, 1 AS v), [1, 2], [STRUCT('k1' AS k)]
);
