CREATE TABLE ds.events (id INT64, updated_at TIMESTAMP);
INSERT INTO ds.events VALUES (1, TIMESTAMP '2024-01-01 00:00:00+00'), (2, TIMESTAMP '2024-01-02 00:00:00+00'), (3, TIMESTAMP '2024-01-03 00:00:00+00');
CREATE VIEW ds.v_events AS SELECT id, updated_at FROM ds.events
